//! Cargo-driven `wscript.exe` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is wscript-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_wWinMainCRTStartup"),
        "x86_64" => ("x86_64-pc-windows-gnu", "wWinMainCRTStartup"),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "wWinMainCRTStartup"),
        o => panic!("wscript-cargo: unsupported arch {o}"),
    };

    let late_libs: &[&str] = match arch.as_str() {
        "x86" => &["engine:uuid", "engine:wine", "engine:oldnames", "sdk/lib/delayimp/libdelayimp_rust.a"],
        "x86_64" => &["engine:uuid", "engine:wine", "engine:oldnames", "sdk/lib/delayimp/libdelayimp_rust.a"],
        "aarch64" => &["engine:uuid", "engine:wine", "engine:oldnames", "sdk/lib/delayimp/libdelayimp_rust.a"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("wscript-rust")
        .c_from_compile_db("wscript_shims", &["base/applications/cmdutils/wscript/rust_varargs_shim.c"])
        .resource_from_rc("base/applications/cmdutils/wscript/rsrc.rc", "wscript_res")
        .delay_import_lib("dll/win32/shlwapi/shlwapi.spec", "shlwapi.dll", "shlwapi")
        .import_lib("dll/win32/shell32/shell32.spec", "shell32.dll", "shell32")
        .import_lib("dll/win32/oleaut32/oleaut32.spec", "oleaut32.dll", "oleaut32")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/advapi32/advapi32.spec", "advapi32.dll", "advapi32")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // ...and those cmake linked after the body, in the same order.
        .static_libs_after_body(late_libs)
        .msvcrtex_crt(MsvcrtexKind::ExeWide)
        .link(ModuleKind::Win32Exe {
            entry: entry.into(),
            subsystem: "windows:5.01".into(),
        });
}
